using System;
using System.Linq;
using System.Collections.Generic;
using System.Text;
public static class BlueprintIncrementChecks {
 static void Require(bool c,string m){if(!c)throw new Exception(m);}
 static ForgeMvp.Evaluation Eval(string code,BlueprintObservation observation=null,ForgeTechnology tech=null)=>BlueprintRuntime.Evaluate(code,0,0,"increment",1,technology:tech,context:new ForgeRunContext{Observation=observation});
 static void Ok(ForgeMvp.Evaluation e)=>Require(e.error==null,e.error);
 static void Value(ForgeMvp.Evaluation e,string name,int expected)=>Require((int)e.values[name]==expected,name+" expected "+expected);
 public static string Run(){var log=new StringBuilder();int count=0;Action<string,Action> test=(name,action)=>{action();count++;log.AppendLine("PASS "+name);};
 test("four operators standalone and expression values without research",()=>{var e=Eval("i=3\na=i++\nb=++i\nc=i--\nd=--i\ni++\ni--\n++i\n--i",tech:new ForgeTechnology());Ok(e);Value(e,"a",3);Value(e,"b",5);Value(e,"c",5);Value(e,"d",3);Value(e,"i",3);});
 test("precedence left to right and short circuit",()=>{var e=Eval("i=2\na=i++ * 10 + ++i\nb=False and i++ > 0\nc=True or ++i > 0\nd=i+++i\ne=-(-i)");Ok(e);Value(e,"a",24);Value(e,"i",5);Value(e,"d",9);Value(e,"e",5);});
 test("list dictionary and index evaluated once with observations",()=>{var o=new BlueprintObservation{Enabled=true};var e=Eval("a=[10,20]\ni=0\nx=a[i++]++\ny=++a[i]\nd={4:8}\nz=d[4]--",o);Ok(e);Value(e,"i",1);Value(e,"x",10);Value(e,"y",21);Value(e,"z",8);Require(((List<int>)e.values["a"]).SequenceEqual(new[]{11,21})&&((Dictionary<int,int>)e.values["d"])[4]==7,"collections");Require(o.History.Contains("a[0] 변경 10 → 11")&&o.History.Contains("i 변경 0 → 1"),"actual trace");});
 test("loop condition increment evaluates once per condition and function locals",()=>{var e=Eval("i=0\ntotal=0\n888(i++ < 3):\n    total=total+i\n333 bump(x):\n    << ++x\nx=10\ny=bump(x++)");Ok(e);Value(e,"i",4);Value(e,"total",6);Value(e,"x",11);Value(e,"y",11);var local=Eval("i=7\n333 bad():\n    i++\nbad()");Require(local.error!=null&&local.errorLine==3&&(int)local.values["i"]==7,"local assignment must initialize");});
 test("invalid targets and nonintegers retain values with original line",()=>{foreach(string tail in new[]{"1++","++(i+1)","i++++","++i++","a[:]++","(1,2)[0]++","[1][0]++"}){var e=Eval("i=4\na=[1]\n"+tail);Require(e.error!=null&&e.errorLine==3,tail);}foreach(string source in new[]{"i=True","i='text'","i=None","i=[1]","i=(1,2)"}){var e=Eval(source+"\ni++");Require(e.error!=null&&e.errorLine==2,source);}var missing=Eval("missing++");Require(missing.error!=null&&missing.errorLine==1,"uninitialized");});
 test("overflow bad indexes and missing keys never mutate target",()=>{foreach(string source in new[]{"i=2147483647\ni++","i=-2147483648\n--i"}){var e=Eval(source);Require(e.error!=null&&e.errorLine==2,"overflow");Value(e,"i",source.Contains("--")?int.MinValue:int.MaxValue);}foreach(string source in new[]{"a=[2147483647]\na[0]++","a=[4]\na[1]++","a=[4]\na[-1]--","a=(4,5)\na[0]++","a={1:4}\na[0]++"}){var e=Eval(source);Require(e.error!=null&&e.errorLine==2,"invalid collection");if(e.values["a"] is List<int> list)Require(list[0]==(source.Contains("2147483647")?int.MaxValue:4),"list unchanged");if(e.values["a"] is Dictionary<int,int> dict)Require(dict.Count==1&&dict[1]==4,"dict unchanged");}});
 test("single stepping never replays increment",()=>{using(var s=BlueprintRuntime.StartSession("i=1\na=i++\nb=++i\nx=[5]\nx[0]--",0,0)){s.Advance().GetAwaiter().GetResult();Value(s.Evaluation,"i",1);s.Advance().GetAwaiter().GetResult();Value(s.Evaluation,"i",2);Value(s.Evaluation,"a",1);while(!s.Completed)s.Advance().GetAwaiter().GetResult();s.Advance().GetAwaiter().GetResult();Value(s.Evaluation,"i",3);Value(s.Evaluation,"b",3);Require(((List<int>)s.Evaluation.values["x"])[0]==4,"single decrement");}});
 test("strings comments raw spans and minus whitespace preserved",()=>{string source="i=3\ns='i++ --i' # ++i\ni--\nx=i - -1";var e=Eval(source);Ok(e);Value(e,"i",2);Value(e,"x",3);Require((string)e.values["s"]=="i++ --i","literal");var tokens=BlueprintLexer.Scan(source);Require(tokens.Count(t=>t.Raw=="--")==1,"opaque strings/comments");foreach(var t in ForgeSyntax.Scan(source))Require(t.start>=0&&t.start+t.length<=source.Length,"raw span");});
 test("guide numeric and English variants execute and remain initially visible",()=>{var entry=BlueprintGuide.Entries.Single(e=>e.Id=="increment");Require(BlueprintResearchGuide.EntryVisible(entry,new ForgeTechnology(),null),"default guide unlock");foreach(bool english in new[]{true,false}){var e=Eval(entry.ExampleFor(english),tech:new ForgeTechnology());Ok(e);Value(e,"a",3);Value(e,"b",5);Value(e,"c",5);Value(e,"d",3);Value(e,"i",3);}});
 return log+"Increment checks: "+count+" passed";
 }
}
